src='''def transform(grid):
    """Complete a grid of repeated parallel bands, with zeros as blanks."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    # Horizontal color bands: a missing band mirrors its opposite band.
    if all(len(set(row)) <= 1 for row in g):
        out = [row[:] for row in g]
        for r in range(h):
            if all(v == 0 for v in out[r]):
                other = h - 1 - r
                if any(v != 0 for v in g[other]):
                    out[r] = g[other][:]
        return out

    # The other examples are cyclic diagonal bands. Find the orientation
    # whose diagonal classes each have a single observed color.
    n = min(h, w)
    best = None
    for mode in (0, 1):  # 0: c-r; 1: c+r
        groups = {}
        conflict = False
        for r in range(h):
            for c in range(w):
                v = g[r][c]
                if v == 0:
                    continue
                key = (c-r if mode == 0 else c+r) % n
                if key in groups and groups[key] != v:
                    conflict = True
                    break
                groups[key] = v
            if conflict:
                break
        if not conflict:
            score = len(groups)
            if best is None or score > best[0]:
                best = (score, mode, groups)
    if best is not None:
        _, mode, groups = best
        out = [row[:] for row in g]
        for r in range(h):
            for c in range(w):
                if out[r][c] == 0:
                    key = (c-r if mode == 0 else c+r) % n
                    if key in groups:
                        out[r][c] = groups[key]
        return out
    return g
'''
