    """Complete a grid made from periodic parallel color bands."""
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])

    # Uniform rows indicate horizontal bands; infer their shortest period.
    if all(len(set(row)) <= 1 for row in g):
        vals = [row[0] for row in g]
        for p in range(1, h + 1):
            groups = {}
            ok = True
            for r, v in enumerate(vals):
                if v == 0:
                    continue
                k = r % p
                if k in groups and groups[k] != v:
                    ok = False
                    break
                groups[k] = v
            if ok:
                return [[groups.get(r % p, 0)] * w for r in range(h)]
        return g

    # Otherwise infer the shortest periodic diagonal bands and their slope.
    candidates = []
    for p in range(1, max(h, w) + 1):
        for mode in (0, 1):  # 0: c-r; 1: c+r
            groups = {}
            ok = True
            for r in range(h):
                for c in range(w):
                    v = g[r][c]
                    if v == 0:
                        continue
                    k = ((c - r) if mode == 0 else (c + r)) % p
                    if k in groups and groups[k] != v:
                        ok = False
                        break
                    groups[k] = v
                if not ok:
                    break
            if ok:
